var t=`0772-rolex-chapati`;var n=`world-0772`;var i=`UG`;var a=`eastern-africa`;var l=8;var s=70;var r={en:`Rolex Chapati`,ua:`Ролекс у чапаті`};var d={en:`Rolex Chapati is a Uganda classic prepared with all-purpose flour, chicken egg, tomato, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ролекс у чапаті, страва кухні країни Уганда зі складниками: пшеничне борошно універсальне, куряче яйце, помідор, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,350,`g`],[`water`,210,`ml`],[`sunflower-oil`,40,`ml`],[`table-salt`,4,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,30,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`chicken-egg`,5,`pcs`],[`tomato`,210,`g`],[`yellow-onion`,150,`g`],[`white-cabbage`,130,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 11 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 11 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:11,i:[[`sunflower-oil`,25,`ml`]]},{en:`Place cooked egg-and-vegetable omelets on warm chapatis, roll each tightly and serve as street-food rolex.`,ua:`Викладіть готовий яєчно-овочевий омлет на теплі чапаті, щільно згорніть рулетом і подавайте ролекс.`,t:[`rolling-stuffed-food`],m:5,i:[]}];var g={slug:t,id:n,country:`UG`,region:a,servings:8,minutes:70,title:r,text:d,steps:u};export{i as country,g as default,n as id,s as minutes,a as region,l as servings,t as slug,u as steps,d as text,r as title};